import{_ as e,o as t,c as r,a5 as i}from"./chunks/framework.BmD0ICqc.js";const m=JSON.parse('{"title":"フレーム生成を切り替えて滑らかさと入力への反応を比べる","description":"","frontmatter":{"title":"フレーム生成を切り替えて滑らかさと入力への反応を比べる","study":{"source":"新規執筆","section":"practice","format":"sample","status":"published","domain":"graphics","collection":"frame-generation-observation","order":1,"summary":"30 Hzで更新するロボットに中間フレームを挿入し、表示する位置の数と、入力で色が変わる時刻を比べる。","aliases":["フレーム生成の実践","フレーム補間","表示FPS","入力遅延","Canvas"],"verification":"AMDのフレーム補間・表示タイミング資料とNVIDIA Streamlineの開発者向け資料に照合（2026-11-13）"}},"headers":[],"relativePath":"practice/graphics/frame-generation-observation.md","filePath":"practice/graphics/frame-generation-observation.md"}'),o={name:"practice/graphics/frame-generation-observation.md"};function s(l,a,n,h,c,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="フレーム生成を切り替えて滑らかさと入力への反応を比べる" tabindex="-1">フレーム生成を切り替えて滑らかさと入力への反応を比べる <a class="header-anchor" href="#フレーム生成を切り替えて滑らかさと入力への反応を比べる" aria-label="Permalink to &quot;フレーム生成を切り替えて滑らかさと入力への反応を比べる&quot;">​</a></h1><p>横に移動するロボットを、両モードとも毎秒30回の基礎フレームで更新します。生成をオンにすると、連続する2枚の間にロボットの中間位置を描きます。<a href="/study/graphics/postprocess/frame-generation.html">フレーム生成の記事</a>で、実際のゲームが動きや遮蔽を扱う方法も図解しています。</p><p><a href="/study/samples/graphics/frame-generation-observation/index.html" target="_self">フレーム生成の比較デモを開く</a></p><h2 id="ロボットの動きを比べる" tabindex="-1">ロボットの動きを比べる <a class="header-anchor" href="#ロボットの動きを比べる" aria-label="Permalink to &quot;ロボットの動きを比べる&quot;">​</a></h2><ol><li>オフのままロボットを見ます。基礎フレームが切り替わるたびに、ロボットが次の位置へ移ります。</li><li><strong>フレーム生成をオンにする</strong>を選びます。ロボットの移動速度と基礎フレームの更新間隔は共通で、画面では途中の位置も通ります。</li><li>**スロー表示（1/4倍速）**を有効にして、表示中のフレームの種類を見ます。オンでは基礎フレームと生成した中間フレームが交互に表示されます。</li></ol><table tabindex="0"><thead><tr><th>設定</th><th>基礎更新の目標</th><th>表示する画像の目標（通常速度）</th></tr></thead><tbody><tr><td>オフ</td><td>30回／秒</td><td>30枚／秒。基礎フレームを表示</td></tr><tr><td>オン</td><td>30回／秒</td><td>60枚／秒。基礎フレームの間に1枚を追加</td></tr></tbody></table><p>中間位置は、連続する2枚のロボットの座標から計算します。例えば <code>xA</code> と <code>xB</code> の中間は <code>xA + (xB - xA) * 0.5</code> です。物体の座標が分かる教材用の実装なので、画像から動きを推定する処理は省いています。</p><h2 id="入力が色に反映されるまでを比べる" tabindex="-1">入力が色に反映されるまでを比べる <a class="header-anchor" href="#入力が色に反映されるまでを比べる" aria-label="Permalink to &quot;入力が色に反映されるまでを比べる&quot;">​</a></h2><ol><li>通常速度に戻して、生成オフで<strong>色を切り替える</strong>を押すか、Spaceキーを押します。入力は次の基礎フレームでロボットの色に反映されます。</li><li>オンにしてもう一度押します。この実践では、オン時の予定表示に1基礎フレーム分の待ちを加え、中間フレームには手前の基礎フレームの色を使います。色が切り替わるのは、入力を反映した基礎フレームが表示されたときです。</li><li>オン・オフそれぞれで数回押し、表の「入力からCanvas更新」と「表示用の待ち（等速）」を比べます。押した時点が基礎更新の直前か直後かによって、次の更新までの待ちも変わります。</li></ol><p>例えばBがシーン開始から約33.3 msで完成したとします。オフではBをそこで表示する予定です。オンではAを約33.3 ms、中間フレームを約50.0 ms、Bを約66.7 msで表示する予定です。このデモの予定表示の差は、通常速度で約33.3 msです。</p><p>Canvasに反映する時刻は、ブラウザーが描画処理を呼ぶ周期にも左右されます。実際の表示枚数にはディスプレイの更新頻度も関わります。入力機器からディスプレイが発光するまでの測定は、<a href="/study/graphics/optimization/input-to-display-latency.html">入力遅延の記事</a>で扱います。</p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><p>生成オンで途中の位置が増えても、ロボットの色を決める処理はいつ走りますか。</p><details class="details custom-block"><summary>解答</summary><p>次の基礎フレームを作る時点です。このデモは基礎フレームの更新で入力を読み、追加した中間フレームでは位置を補間します。</p></details></li><li><p>生成オンとオフの反応時間の差を比べるとき、1回ずつの測定だけでは判断しにくいのはなぜですか。</p><details class="details custom-block"><summary>解答</summary><p>入力が次の基礎更新のどれだけ前に届いたかによって、色が決まるまでの時間も変わるためです。予定表示までの待ちを見ると、この実践が追加した分を分けて確認できます。</p></details></li></ol><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/graphics/postprocess/frame-generation.html">フレーム生成</a>で、画像の動きと遮蔽を使った補間の仕組みを確認する。</li><li><a href="/study/practice/graphics/taau-observation.html">アップスケーリングの実践</a>で、1枚あたりの画素数を変える処理を試す。</li><li><a href="/study/practice/graphics/frame-pacing-observation.html">フレームペーシングの実践</a>で、表示間隔の違いを比べる。</li><li><a href="/study/learn/roadmap.html?node=gfx-postprocess#graphics">3DCG・描画ロードマップの「ポストプロセスとAA」</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://gpuopen.com/manuals/fidelityfx_sdk/techniques/frame-interpolation/" target="_blank" rel="noreferrer">AMD — FidelityFX Frame Interpolation 1.1.3</a> · <a href="https://gpuopen.com/manuals/fsr_sdk/techniques/frame-interpolation-swap-chain/" target="_blank" rel="noreferrer">Frame Generation Swapchain</a></li><li><a href="https://html.spec.whatwg.org/multipage/imagebitmap-and-animations.html#animation-frames" target="_blank" rel="noreferrer">WHATWG HTML — Animation frames</a></li></ul>',17)])])}const u=e(o,[["render",s]]);export{m as __pageData,u as default};
